import{$ as e,A as t,B as n,V as r}from"./chunks/framework.Civ1omIV.js";var i=JSON.parse(`{"title":"Is Clash compatible with sing-box?","description":"How to move sing-box JSON configurations, subscriptions and VLESS, Trojan, Hysteria2, TUIC or AnyTLS nodes to Clash for iOS.","frontmatter":{"title":"Is Clash compatible with sing-box?","description":"How to move sing-box JSON configurations, subscriptions and VLESS, Trojan, Hysteria2, TUIC or AnyTLS nodes to Clash for iOS.","head":[["meta",{"name":"keywords","content":"sing-box iOS,sing-box to Clash,sing-box JSON,mihomo YAML,Hysteria2 iOS,TUIC iOS,AnyTLS iOS"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"FAQPage\\",\\"mainEntity\\":[{\\"@type\\":\\"Question\\",\\"name\\":\\"How do I move a sing-box JSON configuration to Clash?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Clash uses mihomo YAML. Prefer a mihomo subscription or recreate the required nodes and routing intent from the sing-box configuration.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"Can sing-box nodes work in Clash?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Yes when the protocol, transport, TLS, authentication and parameters are supported by Clash. Common VLESS, Trojan, Hysteria2, TUIC and AnyTLS nodes are supported.\\"}}]}"]]},"headers":[],"relativePath":"guide/compatibility/sing-box.md","filePath":"guide/compatibility/sing-box.md","lastUpdated":0}`),a={name:`guide/compatibility/sing-box.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="is-clash-compatible-with-sing-box" tabindex="-1">Is Clash compatible with sing-box? <a class="header-anchor" href="#is-clash-compatible-with-sing-box" aria-label="Permalink to “Is Clash compatible with sing-box?”">​</a></h1><p><strong>Reuse the node protocols and express the configuration as mihomo YAML.</strong></p><p><a href="https://sing-box.sagernet.org/configuration/" target="_blank" rel="noreferrer">sing-box uses JSON configurations</a>, while Clash uses mihomo YAML. Move the nodes, routing intent, and DNS behavior you need into a mihomo YAML configuration.</p><h2 id="which-sing-box-nodes-can-be-reused" tabindex="-1">Which sing-box nodes can be reused? <a class="header-anchor" href="#which-sing-box-nodes-can-be-reused" aria-label="Permalink to “Which sing-box nodes can be reused?”">​</a></h2><p>When their parameters match, common sing-box protocols available in Clash include:</p><ul><li>VLESS;</li><li>Trojan;</li><li>Shadowsocks;</li><li>Hysteria2;</li><li>TUIC;</li><li>AnyTLS;</li><li>WireGuard;</li><li>SSH.</li></ul><p>See the <a href="/clash.md/guide/protocols">complete protocol list</a>.</p><h2 id="fastest-migration-path" tabindex="-1">Fastest migration path <a class="header-anchor" href="#fastest-migration-path" aria-label="Permalink to “Fastest migration path”">​</a></h2><ol><li>Prefer a mihomo / Clash subscription from the provider.</li><li>If only an <code>ss://</code>, <code>vless://</code>, or similar share link is available, convert it to mihomo YAML first or recreate the node from its parameters in Clash.</li><li>Use a standalone node link as a parameter source for YAML or manual entry.</li><li>Rebuild routing and DNS rules that only exist in the sing-box JSON.</li></ol><h2 id="what-to-configure-during-migration" tabindex="-1">What to configure during migration <a class="header-anchor" href="#what-to-configure-during-migration" aria-label="Permalink to “What to configure during migration”">​</a></h2><ul><li>express the sing-box JSON structure as mihomo YAML;</li><li>map the required <code>route</code>, <code>dns</code>, <code>inbounds</code>, and <code>outbounds</code> behavior;</li><li>choose corresponding stable Clash capabilities for experimental options;</li><li>set interface and Apple system preferences in Clash.</li></ul><p>The same server works directly when its protocol, transport, TLS, authentication, and parameter combination is supported by Clash.</p><p>Return to the <a href="/clash.md/guide/compatibility">compatibility overview</a>.</p>`,13)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};